export async function RegisterScopedTools(
  pi: ExtensionAPI,
  input: CreateScopedToolsInput,
): Promise<void>
{
  const { tools } = await BuildScopedTools(input);

  for (const tool of tools)
  {
    pi.registerTool({
      name: tool.name,
      label: tool.label,
