:root
{
  --sheaf-chat-bg: #0b1016;
  --sheaf-chat-surface: #141c27;
  --sheaf-chat-surface-muted: #1c2735;
  --sheaf-chat-border: #2a384c;
  --sheaf-chat-text: #e8eef7;
  --sheaf-chat-muted: #8fa0b8;
  --sheaf-chat-accent: #4f8cff;
  --sheaf-chat-danger: #f87171;
  --sheaf-chat-touch: 44px;
  --agui-chat-bg: var(--sheaf-chat-bg);
  --agui-chat-surface: var(--sheaf-chat-surface);
  --agui-chat-surface-muted: var(--sheaf-chat-surface-muted);
  --agui-chat-border: var(--sheaf-chat-border);
  --agui-chat-text: var(--sheaf-chat-text);
  --agui-chat-muted: var(--sheaf-chat-muted);
  --agui-chat-accent: var(--sheaf-chat-accent);
  --agui-chat-warning: #f59e0b;
  --agui-chat-live: #22c55e;
}

*
{
  box-sizing: border-box;
}

html,
body
{
  height: 100%;
  margin: 0;
}

.sheaf-chat-body
{
  background: var(--sheaf-chat-bg);
  color: var(--sheaf-chat-text);
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

.sheaf-chat-app
{
  min-height: 100%;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

.sheaf-chat-screen
{
  display: flex;
  flex-direction: column;
  min-height: 100%;
  min-height: 100dvh;
}

.sheaf-chat-header
{
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-surface);
  flex-shrink: 0;
}

.sheaf-chat-header-title
{
  font-size: 16px;
  font-weight: 700;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sheaf-chat-back,
.sheaf-chat-button,
.sheaf-chat-icon-button
{
  min-height: var(--sheaf-chat-touch);
  min-width: var(--sheaf-chat-touch);
  border-radius: 8px;
  border: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-surface-muted);
  color: var(--sheaf-chat-text);
  font: inherit;
  cursor: pointer;
  padding: 0 14px;
}

.sheaf-chat-icon-button
{
  width: var(--sheaf-chat-touch);
  padding: 0;
}

.sheaf-chat-back
{
  padding: 0 12px;
}

.sheaf-chat-button--primary
{
  background: var(--sheaf-chat-accent);
  border-color: transparent;
  color: #fff;
}

.sheaf-chat-button:disabled,
.sheaf-chat-icon-button:disabled
{
  opacity: 0.5;
  cursor: not-allowed;
}

.sheaf-chat-content
{
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
}

.sheaf-chat-list
{
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sheaf-chat-list-item
{
  border: 1px solid var(--sheaf-chat-border);
  border-radius: 10px;
  background: var(--sheaf-chat-surface);
}

.sheaf-chat-list-button
{
  width: 100%;
  min-height: var(--sheaf-chat-touch);
  border: none;
  background: transparent;
  color: inherit;
  text-align: left;
  padding: 12px;
  cursor: pointer;
  font: inherit;
}

.sheaf-chat-list-meta
{
  display: block;
  font-size: 12px;
  color: var(--sheaf-chat-muted);
  margin-top: 4px;
}

.sheaf-chat-form
{
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  border-top: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-surface);
  flex-shrink: 0;
}

.sheaf-chat-field
{
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sheaf-chat-label
{
  font-size: 12px;
  color: var(--sheaf-chat-muted);
}

.sheaf-chat-input,
.sheaf-chat-select,
.sheaf-chat-textarea
{
  width: 100%;
  min-height: var(--sheaf-chat-touch);
  border-radius: 8px;
  border: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-bg);
  color: var(--sheaf-chat-text);
  font: inherit;
  padding: 10px 12px;
}

.sheaf-chat-textarea
{
  resize: vertical;
  min-height: 72px;
  max-height: 200px;
  line-height: 1.4;
}

.sheaf-chat-error
{
  color: var(--sheaf-chat-danger);
  font-size: 13px;
}

.sheaf-chat-empty
{
  color: var(--sheaf-chat-muted);
  font-size: 14px;
  padding: 8px 0;
}

.sheaf-chat-chat-layout
{
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.sheaf-chat-chat-main
{
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.sheaf-chat-chat-main .agui-chat-root
{
  flex: 1;
  min-height: 0;
}

.sheaf-chat-chat-status
{
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 8px 12px;
  border-bottom: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-surface);
  font-size: 12px;
  color: var(--sheaf-chat-muted);
  flex-shrink: 0;
}

.sheaf-chat-chat-status strong
{
  color: var(--sheaf-chat-text);
}

.sheaf-chat-model-select
{
  min-height: var(--sheaf-chat-touch);
  border-radius: 8px;
  border: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-bg);
  color: var(--sheaf-chat-text);
  font: inherit;
  padding: 0 10px;
  max-width: 100%;
}

.sheaf-chat-composer
{
  display: flex;
  gap: 8px;
  align-items: flex-end;
  padding: 10px 12px calc(10px + env(safe-area-inset-bottom, 0px));
  border-top: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-surface);
  position: sticky;
  bottom: 0;
  flex-shrink: 0;
}

.sheaf-chat-composer .sheaf-chat-textarea
{
  flex: 1;
  min-width: 0;
}

.sheaf-chat-send
{
  min-height: var(--sheaf-chat-touch);
  min-width: var(--sheaf-chat-touch);
  flex-shrink: 0;
}

.sheaf-chat-composer--disconnected .sheaf-chat-textarea
{
  opacity: 0.7;
}

.sheaf-chat-composer--queued .sheaf-chat-send::after
{
  content: " *";
}

.sheaf-chat-touch .sheaf-chat-send
{
  display: inline-flex;
}

